# frozen_string_literal: true

require 'rails_helper'

RSpec.describe 'auth setup cost', type: :request do
  it 'measures' do
    Fabricate(:user) # warm up
    n = 50
    t_user = Benchmark.realtime { n.times { Fabricate(:user) } }
    users = Array.new(n) { Fabricate(:user) }
    t_token = Benchmark.realtime { users.each { |u| Fabricate(:accessible_access_token, resource_owner_id: u.id, scopes: 'read') } }
    t_status = Benchmark.realtime { n.times { Fabricate(:status) } }
    t_account = Benchmark.realtime { n.times { Fabricate(:account) } }
    t_remote = Benchmark.realtime { n.times { Fabricate(:account, domain: 'example.com') } }
    puts format("\nuser: %.1fms, token: %.1fms, status: %.1fms, local account: %.1fms, remote account: %.1fms", t_user / n * 1000, t_token / n * 1000, t_status / n * 1000, t_account / n * 1000, t_remote / n * 1000)
  end
end
EOF
TEST_ENV_NUMBER=3 bundle exec rspec tmp/scratch/auth_cost_spec.rb 2>&1 | grep -E "user:|examples"

