require 'json'
def load(p) = JSON.parse(File.read(p))
s1 = load('tmp/prof/times_step1.json'); s2 = load('tmp/prof/times_step2.json')
puts "step1 total: #{s1['summary']['duration'].round(1)}s (#{s1['summary']['failure_count']} failures), step2 total: #{s2['summary']['duration'].round(1)}s (#{s2['summary']['failure_count']} failures)"
by_file = ->(r) { r['examples'].group_by { _1['file_path'] }.transform_values { |es| es.sum { _1['run_time'] } } }
f1 = by_file.(s1); f2 = by_file.(s2)
changed = %w(./spec/requests/signature_verification_spec.rb ./spec/requests/api/v1/csp_spec.rb ./spec/requests/api/v1/notifications_spec.rb ./spec/requests/api/v2/notifications_spec.rb)
c1 = changed.sum { f1[_1] }; c2 = changed.sum { f2[_1] }
o1 = f1.except(*changed).values.sum; o2 = f2.except(*changed).values.sum
puts format('changed files: %.1fs -> %.1fs; other files: %.1fs -> %.1fs', c1, c2, o1, o2)
changed.each { |f| puts format('  %-55s %.2fs -> %.2fs', f, f1[f], f2[f]) }
puts 'biggest differences in other files:'
f1.except(*changed).map { |f, t| [f, t, f2[f]] }.sort_by { |_, a, b| b - a }.first(8).each { |f, a, b| puts format('  %-60s %.2fs -> %.2fs', f, a, b) }
# examples right after a signature verification example (in run order)
order = s1['examples'].map { _1['file_path'] }
RUBY
sleep 120; ls tmp/prof/ | grep -E "times_|compare"

